const introChapters=[{title:'Глава 1. Чтение — это путешествие',paras:[
'Книга становится полезной не тогда, когда ты её купил, а тогда, когда ты начал замечать важные мысли и применять их в своей жизни.',
'Не нужно читать быстро. Попробуй читать пятнадцать минут в день, но регулярно. Время, которое ты действительно провёл с книгой, гораздо ценнее списка невыполненных планов.',
'Когда встречается незнакомое слово, нажми на него. ATLAS попробует найти значение в словаре. Можно также выделить цитату или сохранить место, на котором остановился.',
'Перед тем как закрыть читалку, нажми на любой абзац. Ты увидишь вопрос: «Сохранить это место?». При следующем открытии книга начнётся там, где ты остановился.'
]},{title:'Глава 2. Учись понимать, а не запоминать всё',paras:[
'После главы спроси себя: какую одну главную идею хотел передать автор? С чем я согласен, а с чем нет? Что я могу попробовать сделать иначе уже завтра?',
'В ATLAS есть раздел «Итоги главы». Он выделяет важные предложения из прочитанного текста и помогает вернуться к основным мыслям. Это автоматическое извлечение фрагментов, а не гарантированно точный пересказ.',
'Книга может быть убедительной и при этом ошибочной. Сравнивай идеи с данными и другими точками зрения. Особенно важно это при чтении книг о власти, деньгах и психологии.',
'Запиши одну полезную мысль. Этого достаточно, чтобы чтение понемногу превращалось в навык.'
]},{title:'Глава 3. Составь свой маршрут',paras:[
'Начни с простой и интересной книги. Если тебе пятнадцать лет, попробуй приключения, популярную науку или книги о привычках. Если работаешь с командой — полезны переговоры и психология общения.',
'Не нужно безоговорочно следовать чужим советам. Приложение предлагает книги под конкретные цели, но читатель всегда принимает решения самостоятельно.',
'Добавляй полные тексты в форматах TXT, FB2, EPUB или текстовых PDF. Файлы остаются в браузере на этом устройстве. Для работы на нескольких устройствах можно сохранить резервную копию.',
'Пусть чтение будет не гонкой за количеством, а способом лучше понимать себя, людей и мир вокруг.'
]}];
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s||'').toLocaleLowerCase('ru').normalize('NFKC').replace(/ё/g,'е');
const trunc=(s,n)=>String(s||'').length>n?String(s).slice(0,n-1)+'…':s;
function save(){try{localStorage.setItem(STKEY,JSON.stringify(st))}catch(_){toast('Недостаточно памяти: сделай резервную копию')}}
function toast(str){const el=$('#toast');el.textContent=str;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2700)}
function dayKey(){return new Date().toLocaleDateString('en-CA')}
function bookById(id){return [intro,...savedBooks,...curated,...Object.values(st.savedCatalog||{}),...view.remoteResults,...view.gutResults].find(b=>b.id===id)}
function allBooks(){return [intro,...savedBooks,...curated]}
function cover(b,extra=''){const palette=colors[((b.index ?? Number(String(b.id).replace(/\D/g,''))) || 0)%colors.length];const img=b.image||st.customCovers[b.id]||(b.isbn?`https://covers.openlibrary.org/b/isbn/${encodeURIComponent(b.isbn)}-M.jpg?default=false`:null);return `<div class="cover ${extra}" style="--cover1:${palette[0]};--cover2:${palette[1]}">${img?`<img src="${safe(img)}" alt="Обложка ${safe(b.title)}" loading="lazy" onerror="this.remove()">`:''}<div class="cover-content"><span class="cover-author">${safe(trunc(b.author,31))}</span><strong class="cover-title">${safe(trunc(b.title,56))}</strong><div class="cover-glyph">✧ &nbsp; ATLAS &nbsp; ✧</div></div></div>`}
function bookCard(b){return `<article class="book-card" data-book="${safe(b.id)}" tabindex="0" role="button" aria-label="Открыть ${safe(b.title)}">${cover(b)}<div class="book-title">${safe(b.title)}</div><div class="book-author">${safe(b.author)}</div><div class="book-tag">${b.source==='import'?'✓ Текст загружен':b.source==='sample'?'✓ Можно читать':b.source==='gutenberg'?'Свободная библиотека':safe(b.category)}</div></article>`}
function bookList(b,desc){return `<article class="list-book" data-book="${safe(b.id)}">${cover(b)}<div style="min-width:0;flex:1"><h3>${safe(b.title)}</h3><p>${safe(b.author)} · ${safe(b.category)}</p>${desc?`<p class="list-desc">${safe(trunc(desc,125))}</p>`:''}${st.progress[b.id]?`<div class="progress-line"><span style="width:${Number(st.progress[b.id].percent)||0}%"></span></div>`:''}</div><span class="more">›</span></article>`}
function heading(title,link='',action=''){return `<div class="section-heading"><h2>${title}</h2>${link?`<button class="link-btn" data-action="${action}">${link} →</button>`:''}</div>`}
function dateStr(){return new Intl.DateTimeFormat('ru',{day:'numeric',month:'long'}).format(new Date())}
function home(){const rec=st.recent.map(bookById).filter(Boolean);const best=[curated[6],curated[1],curated[0],curated[22],curated[38],curated[50],curated[48],curated[41],curated[32],curated[12]];const hero=rec[0]||curated[6];let count=Object.values(st.progress).filter(x=>x.percent<99).length;return `
<section class="hero"><div class="hero-copy"><span class="eyebrow">✦ &nbsp; ТВОЯ ЛИЧНАЯ БИБЛИОТЕКА</span><h1>Большие идеи.<br><span style="color:#efc783">Одна книга</span><br>за другой.</h1><p>Читай в своём ритме. Понимай сложные слова. Возвращайся к главному.</p><button class="btn" data-action="${rec.length?'resume-first':'open-sample'}">${rec.length?'Продолжить чтение':'Начать читать'} &nbsp; ↗</button></div><div class="hero-art"><div class="orbit"></div>${cover(hero,'hero-book')}</div></section>
<div class="mini-stats"><div class="mini-stat"><b>${count}</b><span>Книг в процессе</span></div><div class="mini-stat"><b>${Object.values(st.progress).filter(x=>x.percent>=99).length}</b><span>Прочитано книг</span></div><div class="mini-stat"><b>${st.goal} мин</b><span>Цель на день</span></div></div>
${rec.length?heading('Продолжить чтение','Моя библиотека','to-library')+`<div class="list-books">${rec.slice(0,2).map(b=>bookList(b)).join('')}</div>`:''}
${heading('Под настроение','Все направления','to-catalog')}<div class="tiles">${[['🧠','Психология','Понять себя'],['🏛','Философия','Мыслить глубже'],['📈','Бизнес','Расти и создавать'],['🌌','Наука','Узнать мир']].map(([e,c,d])=>`<button class="tile" data-category="${c}"><span class="tile-icon">${e}</span><strong>${c}</strong><span>${d}</span></button>`).join('')}</div>
${heading('Выбор ATLAS','Открыть каталог','to-catalog')}<div class="book-grid">${best.slice(0,10).map(bookCard).join('')}</div>
${heading('Тебе пригодится')}<div class="split"><div class="feature-card"><span class="eyebrow">ПЕРСОНАЛЬНЫЙ ПОДБОР</span><h3>«Хочу перестать лениться»</h3><p>Напиши свою проблему — получи подходящие книги и понятный маршрут чтения.</p><button class="btn sm" data-action="to-advisor">Подобрать книги →</button></div><div class="feature-card gold"><span class="eyebrow">СТАРТ С НУЛЯ</span><h3>Что читать в 15 лет?</h3><p>Доступные книги для начинающих и отдельные подборки для взрослых.</p><button class="btn secondary sm" data-action="age-15">Выбрать →</button></div></div>`}
function filteredLocal(){let books=allBooks();if(view.category!=='Все')books=books.filter(b=>b.category===view.category||view.category==='Для подростков'&&b.age<=15);if(view.age==='15')books=books.filter(b=>b.age<=15);if(view.age==='adult')books=books.filter(b=>b.age>=16);if(view.query.trim()){const q=norm(view.query.trim());books=books.filter(b=>norm([b.title,b.author,b.category,...b.tags,b.desc].join(' ')).includes(q))}return books}
function catalog(){let books=filteredLocal();return `<div class="page-head"><span class="eyebrow">ОТКРЫВАЙ НОВОЕ</span><h1>Каталог книг</h1><p class="subtle">Подборки по интересам, возрасту и задачам. Обложки и описания — не гарантия наличия полного текста.</p></div><div class="search-wrap"><span>⌕</span><input id="catalogSearch" value="${safe(view.query)}" placeholder="Книга, автор, тема или проблема…" autocomplete="off"><button class="link-btn" data-action="world-search">Найти в мире</button></div><div class="category-row">${cats.map(c=>`<button class="chip ${c===view.category?'selected':''}" data-category="${safe(c)}">${catEmojis[c]||'✧'} ${safe(c)}</button>`).join('')}</div><div class="row" style="margin-top:15px"><button class="chip ${view.age==='all'?'selected':''}" data-age="all">Все возрасты</button><button class="chip ${view.age==='15'?'selected':''}" data-age="15">До 15 лет</button><button class="chip ${view.age==='adult'?'selected':''}" data-age="adult">Старше 15</button><span class="small-caps right">${books.length} книг</span></div>${heading('Избранные книги')} ${books.length?`<div class="book-grid">${books.map(bookCard).join('')}</div>`:`<div class="empty"><span class="symbol">⌕</span><h3>Ничего не найдено</h3>Попробуй другое слово или поиск в мировом каталоге.</div>`}
${view.onlineBusy?`<div class="skeleton" style="margin-top:20px"></div>`:''}${view.openLibraryResults.length?`${heading('Результаты мирового каталога')}<p class="subtle" style="font-size:12px">Это библиографические записи, не полные тексты. Читать можно после загрузки своего файла или из легальных открытых источников.</p><div class="book-grid">${view.openLibraryResults.map(bookCard).join('')}</div>`:''}${view.gutResults.length?`${heading('Свободные тексты Project Gutenberg')}<div class="book-grid">${view.gutResults.map(bookCard).join('')}</div>`:''}
<div class="feature-card" style="margin-top:28px"><span class="eyebrow">ЕЩЁ БОЛЬШЕ КНИГ</span><h3>Найти оригинальный текст бесплатно</h3><p>Поиск по Project Gutenberg — источнику книг, доступных для свободного распространения в США. Права на текст и перевод в вашей стране могут отличаться.</p><button class="btn secondary sm" data-action="gutenberg-search">Искать свободные книги →</button></div>`}
const routeDefs=[
{re:/лен|прокраст|не могу начать|откладыва|дисциплин|ничего не дел|привычк|мотивац/i,title:'Победить прокрастинацию',why:'Не стремись «никогда не лениться»: отдых нормален. Лучше построить привычку начинать с маленького действия.',ids:[6,19,7,17,36],plan:'Начни с «Атомных привычек»: выбери одно действие на 2 минуты и повторяй его неделю.'},
{re:/общен|друз|знаком|застен|стесн|разгов|одинок|отношен/i,title:'Стать увереннее в общении',why:'Полезнее не производить впечатление любой ценой, а учиться слушать и уважать границы.',ids:[0,15,11,13,24],plan:'После каждой главы попробуй один приём активного слушания.'},
{re:/учеб|школ|экзам|оценк|запомина|математ|внимани|концентр/i,title:'Учиться легче и увереннее',why:'Начни с техники учёбы, сна и управления вниманием, а не с сверхдлинных списков задач.',ids:[46,7,37,6,16],plan:'Выделяй 25 минут на одну сложную тему и делай короткий перерыв.'},
{re:/ден|богат|финанс|инвест|доход|бюджет/i,title:'Разобраться с деньгами',why:'Популярные финансовые книги дают идеи, но не заменяют проверенных источников или индивидуального совета.',ids:[28,29,31,30,35],plan:'Записывай расходы и сравнивай идеи авторов с реальными фактами.'},
{re:/тревог|стресс|страх|уверен|самооцен|неудач|груст|пережив/i,title:'Лучше понять себя',why:'Книги могут поддержать, но при сильном или длительном дискомфорте важнее помощь близких и специалиста.',ids:[1,2,12,13,77],plan:'Обращай внимание, какие мысли и обстоятельства находятся под твоим контролем.'},
{re:/лидер|бизнес|команд|стратег|управ|делег|карьер/i,title:'Развиваться в работе',why:'Здесь важны системное мышление, работа с людьми и проверка решений на практике.',ids:[33,34,25,23,35],plan:'После каждой книги формулируй одно проверяемое изменение для команды.'},
{re:/смысл|жизн|счаст|зачем|цель|будущ/i,title:'Найти свои ориентиры',why:'Философские книги не дают универсального ответа, зато учат задавать более точные вопросы.',ids:[1,13,2,16,27],plan:'Записывай в двух предложениях, с чем ты согласен, а с чем нет.'},
{re:/наук|космос|биолог|истор|мир|факт/i,title:'Понять устройство мира',why:'Сначала увлекательные обзоры, затем более сложные первоисточники.',ids:[43,44,39,45,40],plan:'Выбирай по одной теме после главы для дополнительной проверки.'}
];
function makeRecommendations(query,persona){const q=norm(query);let match=routeDefs.find(r=>r.re.test(q));if(!match){if(persona==='15')match={title:'Интересное чтение для 15 лет',why:'Лучше начать с понятной и захватывающей книги, а затем попробовать нон-фикшн.',ids:[50,56,78,46,6],plan:'Читайте 10–15 минут ежедневно и меняйте книгу, если она совсем не увлекает.'};else if(persona==='beginner')match={title:'Хороший старт для новичка',why:'Выбирай короткие главы, ясный язык и близкие интересы.',ids:[31,50,54,6,1],plan:'Начни с 10 страниц и запиши одну интересную мысль.'};else if(persona==='adult')match={title:'Подборка для взрослого',why:'Книги, которые помогают принимать решения, развивать мышление и работать с людьми.',ids:[33,12,29,22,1],plan:'Не гонись за количеством: оценивай идеи на практике.'};else match={title:'Универсальная подборка',why:'Разные жанры помогут найти свой способ читать с удовольствием.',ids:[6,1,50,43,12],plan:'Выбери первую книгу по интересу, а не по рейтингу.'}}let bs=match.ids.map(i=>curated[i]).filter(Boolean);if(persona==='15')bs=bs.filter(b=>b.age<=15).concat(curated.filter(b=>b.age<=15).slice(0,5)).filter((b,i,a)=>a.findIndex(x=>x.id===b.id)===i).slice(0,5);return {...match,books:bs}}
function advisor(){const r=view.rec;return `<div class="page-head"><span class="eyebrow">✦ &nbsp; ПЕРСОНАЛЬНЫЙ НАВИГАТОР</span><h1>Книги под твою жизнь</h1><p class="subtle">Не знаешь, что читать? Опиши проблему, цель или настроение обычными словами.</p></div><div class="advisor-box"><span class="eyebrow">КОМУ ИЩЕМ КНИГУ?</span><div class="persona-row" style="margin-top:13px">${[['all','Любому возрасту'],['beginner','Начинающему'],['15','Мне 15 лет'],['adult','Взрослому']].map(([v,t])=>`<button class="persona ${st.persona===v?'active':''}" data-persona="${v}">${t}</button>`).join('')}</div><textarea id="problemInput" placeholder="Например: хочу перестать откладывать дела, научиться общаться, лучше учиться, стать увереннее…">${safe(view.problem||'')}</textarea><div class="row"><button class="btn" data-action="get-recs">Подобрать мой маршрут ✧</button><span class="subtle" style="font-size:11px">Без регистрации и ожидания</span></div><div class="row" style="margin-top:17px">${['Хочу перестать лениться','Мне 15, с чего начать?','Хочу больше зарабатывать','Научиться общаться'].map(t=>`<button class="chip" data-prompt="${safe(t)}">${safe(t)}</button>`).join('')}</div></div>${r?`<div class="recommendation"><span class="eyebrow">ТВОЙ МАРШРУТ</span><h2 style="font-family:Georgia,serif;font-size:26px;margin:11px 0">${safe(r.title)}</h2><p>${safe(r.why)}</p><p><b>С чего начать:</b> ${safe(r.plan)}</p></div>${heading('Рекомендуем в таком порядке')}<div class="list-books">${r.books.map((b,i)=>bookList(b,`${i+1}. ${b.desc}`)).join('')}</div>`:`${heading('Популярные маршруты')}<div class="tiles">${[['⏳','Перестать откладывать','Хочу перестать лениться'],['🗣','Лучше общаться','Мне сложно общаться'],['🎓','Учиться эффективнее','Хочу лучше учиться'],['✨','Начать в 15 лет','Мне 15, с чего начать?']].map(([icon,title,q])=>`<button class="tile" data-prompt="${safe(q)}"><span class="tile-icon">${icon}</span><strong>${title}</strong><span>Получить подборку →</span></button>`).join('')}</div>`}<p class="subtle" style="font-size:11px;margin-top:23px">Рекомендации строятся по темам и возрасту; это локальный подборщик, не медицинская или профессиональная консультация.</p>`}
function library(){const imported=savedBooks;const fav=st.likes.map(bookById).filter(Boolean);const recent=st.recent.map(bookById).filter(Boolean);return `<div class="page-head"><span class="eyebrow">ТВОЁ ПРОСТРАНСТВО</span><h1>Моя библиотека</h1><p class="subtle">Книги, закладки и твой собственный темп чтения.</p></div><div class="import-panel"><span class="eyebrow">СВОИ ОРИГИНАЛЫ</span><h3 style="font-family:Georgia,serif;font-size:24px;margin:12px 0 8px">Добавь собственную книгу</h3><p class="subtle" style="font-size:12px">TXT, FB2, EPUB и текстовые PDF. Доступно для чтения даже без интернета после загрузки.</p><button class="btn" data-action="import-book">⊕ &nbsp; Загрузить файл</button></div>${heading('Читаю сейчас')} ${recent.length?`<div class="list-books">${recent.map(b=>bookList(b)).join('')}</div>`:`<div class="empty"><span class="symbol">◈</span><h3>Здесь будут твои книги</h3>Попробуй встроенную книгу ATLAS или загрузи свою.<div style="margin-top:17px"><button class="btn sm" data-action="open-sample">Открыть пример</button></div></div>`}${heading('Мои файлы')} ${imported.length?`<div class="list-books">${imported.map(b=>bookList(b)).join('')}</div>`:`<p class="subtle" style="font-size:12px">Загруженных файлов пока нет.</p>`}${heading('Сохранённое')} ${fav.length?`<div class="book-grid">${fav.map(bookCard).join('')}</div>`:`<p class="subtle" style="font-size:12px">Нажимай ♡ на странице книги, чтобы добавить сюда.</p>`}<div class="feature-card" style="margin-top:30px"><h3>Твоя библиотека — твои данные</h3><p>Книги и прогресс хранятся в браузере этого устройства. Для переноса на другое устройство экспортируй резервную копию и импортируй её там.</p><div class="row"><button class="btn secondary sm" data-action="export">↓ Резервная копия</button><button class="btn ghost sm" data-action="restore">↑ Восстановить</button></div></div>`}
function detail(b){const owned=b.source==='import'||b.source==='sample'||Boolean(view.bookContents?.id===b.id);const pct=st.progress[b.id]?.percent||0;const fav=st.likes.includes(b.id);return `<div class="row" style="margin-top:27px"><button class="link-btn" data-action="back">← Назад к книгам</button></div><section class="detail-layout"><div>${cover(b,'detail-cover')}${b.source==='import'?`<button class="btn ghost sm" data-action="set-cover" style="margin-top:16px;width:100%">▧ Сменить обложку</button>`:''}</div><div class="detail-main"><span class="eyebrow">${safe(b.category)}</span><h1>${safe(b.title)}</h1><div class="subtle">${safe(b.author)}</div><div class="meta-bullet">${b.age||12}+ &nbsp;·&nbsp; ${b.source==='import'?'Мой оригинальный файл':b.source==='sample'?'Встроенный текст':b.source==='gutenberg'?'Project Gutenberg':'Книга из каталога'}</div><div class="tag-row">${(b.tags||[]).slice(0,4).map(t=>`<span class="pill">#${safe(t)}</span>`).join('')}</div><div class="row"><button class="btn" data-action="read">${owned?'Читать книгу':b.source==='gutenberg'?'Загрузить оригинал':'Добавить оригинал'} ↗</button><button class="btn ghost" data-action="favorite">${fav?'♥ В сохранённом':'♡ Сохранить'}</button></div>${pct?`<div style="margin-top:16px"><span class="small-caps">Твой прогресс · ${pct}%</span><div class="progress-line"><span style="width:${pct}%"></span></div></div>`:''}</div><div class="detail-full"><div class="info-panel"><span class="eyebrow">О КНИГЕ</span><p class="subtle">${safe(b.desc||'Описание этой книги ещё не добавлено.')}</p></div>${!owned?`<div class="muted-box"><strong>Как читать полный оригинал?</strong> Для современных книг каталог показывает информацию, но не распространяет текст без разрешения. Загрузи приобретённый или полученный легально EPUB/FB2/TXT/PDF. Для классики доступен поиск произведений из Project Gutenberg.${b.external?` <a href="${safe(b.external)}" target="_blank" rel="noopener">Посмотреть источник</a>.`:''}</div>`:''}${b.source==='import'?`<button class="link-btn" data-action="delete-book" style="margin-top:22px;color:#ff9f9f">Удалить книгу с этого устройства</button>`:''}</div></section>`}
function render(){if(view.tab==='reader')return;view.tab=view.tab||'home';$('#topbar').classList.remove('hidden');$('#bottomNav').classList.remove('hidden');$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===view.tab));app.innerHTML=view.book?detail(view.book):view.tab==='catalog'?catalog():view.tab==='advisor'?advisor():view.tab==='library'?library():home();attachBookEvents();$('#todayDate').textContent=dateStr();$('#userAvatar').textContent=safe((TG?.initDataUnsafe?.user?.first_name||'A').slice(0,1).toUpperCase());if(view.tab==='catalog'&&!view.book){const inp=$('#catalogSearch');inp?.addEventListener('input',e=>{let x=e.target.value;let cursor=e.target.selectionStart;view.query=x;const grid=$('.book-grid');if(grid){const filtered=filteredLocal();grid.innerHTML=filtered.map(bookCard).join('')||'<p class="subtle">Ничего не найдено — попробуй мировой каталог</p>';attachBookEvents();}const count=$('.small-caps.right');if(count)count.textContent=filteredLocal().length+' книг';});}}
function attachBookEvents(){$$('[data-book]').forEach(el=>{el.onclick=()=>openBook(el.dataset.book);el.onkeydown=e=>{if(e.key==='Enter')openBook(el.dataset.book)}})}
function tab(t){view.book=null;view.bookContents=null;view.tab=t;render();window.scrollTo(0,0)}
function openBook(id){const b=bookById(id)||view.openLibraryResults.find(x=>x.id===id);if(!b){toast('Книга не найдена');return}view.book=b;render();window.scrollTo(0,0)}
function modal(html){overlay.hidden=false;overlay.innerHTML=`<div class="modal-layer"><div class="modal" role="dialog" aria-modal="true">${html}</div></div>`;$('.modal-layer').addEventListener('click',e=>{if(e.target.classList.contains('modal-layer'))closeModal()});}
function closeModal(){overlay.hidden=true;overlay.innerHTML=''}
function standardModal(title,body,actions=`<button class="btn secondary" data-modal="close">Закрыть</button>`){modal(`<h2>${title}</h2>${body}<div class="modal-actions">${actions}</div>`)}
function setProgress(b,ci,pi,chapters,scrollTop){const total=chapters.reduce((s,ch)=>s+ch.paras.length,0)||1;const passed=chapters.slice(0,ci).reduce((s,ch)=>s+ch.paras.length,0)+pi;const percent=Math.min(100,Math.round((passed+1)/total*100));st.progress[b.id]={chapter:ci,para:pi,percent,at:Date.now(),scrollTop:scrollTop||0};st.readDays[dayKey()]=true;st.recent=[b.id,...st.recent.filter(x=>x!==b.id)].slice(0,15);save();return percent}
function chapterize(text){let s=String(text||'').replace(/\r\n/g,'\n').replace(/\r/g,'\n').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'').trim();if(!s)return [];let chunks=s.split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean);if(chunks.length<5)chunks=s.split(/\n/).map(x=>x.trim()).filter(Boolean);const paras=[];for(const chunk of chunks){if(chunk.length>2300){const sentences=chunk.match(/[^.!?。]+[.!?。]+\s*|[^.!?。]+$/g)||[chunk];let buf='';for(const sentence of sentences){if(buf.length+sentence.length>1300&&buf){paras.push(buf.trim());buf=''}buf+=sentence}if(buf.trim())paras.push(buf.trim())}else paras.push(chunk)}const chapters=[];let body=[],chars=0,title='Начало';for(const p of paras){const isHeading=p.length<95&&/^(глава|часть|chapter|book\s+[ivx\d]+|пролог|эпилог|предисловие|введение|\d+\.|[IVX]+\.)\b/i.test(p);if((isHeading&&body.length>1)||(chars>16000&&body.length>8)){chapters.push({title,paras:body});body=[];chars=0;title=isHeading?p:`Часть ${chapters.length+1}`;if(isHeading)continue}if(isHeading&&body.length===0){title=p;continue}body.push(p);chars+=p.length}if(body.length)chapters.push({title,paras:body});return chapters.length?chapters:[{title:'Текст',paras:paras.slice(0,10000)}]}
function smartSummary(ch){const text=ch.paras.join(' ');const sentences=(text.match(/[^.!?。\n]+[.!?。]+|[^.!?。\n]+$/g)||[]).map(s=>s.trim()).filter(s=>s.length>35&&s.length<270);const words=norm(text).match(/[а-яa-z]{4,}/g)||[];const stop=new Set('когда который чтобы потому только после перед также однако может нужно потом время просто однако очень какие этот такая такой того своим своего всех меня тебя всего было было если есть люди более тоже даже чтобы were there this that with have which them your about when into from they than because'.split(' '));const freq={};words.forEach(w=>{if(!stop.has(w))freq[w]=(freq[w]||0)+1});const scored=sentences.map((s,i)=>({s,i,score:(norm(s).match(/[а-яa-z]{4,}/g)||[]).reduce((sum,w)=>sum+(freq[w]||0),0)/Math.sqrt(s.length)}));const top=scored.sort((a,b)=>b.score-a.score).slice(0,3).sort((a,b)=>a.i-b.i).map(x=>x.s);return top.length?top:ch.paras.slice(0,3).map(p=>trunc(p,210))}
function recap(){const ch=view.bookContents?.chapters[view.chapter];if(!ch)return;const top=smartSummary(ch);standardModal('Суть этой главы',`<span class="eyebrow">${safe(ch.title)}</span><p>Автоматически выделены ключевые фрагменты исходного текста. Проверь их по книге: это не ИИ-пересказ.</p>${top.map((p,i)=>`<div class="lesson-row"><span class="eyebrow">МЫСЛЬ ${i+1}</span><p>${safe(p)}</p></div>`).join('')}<h3 style="font-family:Georgia,serif">Перед продолжением</h3><p>• Какую главную мысль ты запомнил?<br>• Что тебя удивило или с чем ты не согласен?<br>• Где это можно применить?</p>`)}
async function beginReading(){const b=view.book;if(!b)return;let chapters=[];if(b.source==='sample')chapters=introChapters;else if(b.source==='import'){const record=await dbGet(b.id);if(!record){toast('Файл этой книги недоступен. Импортируй его ещё раз.');return}chapters=record.chapters||chapterize(record.text)}else if(b.source==='gutenberg'){
const candidates=Object.entries(b.formats||{}).filter(([mime,url])=>mime.startsWith('text/plain')&&/^https:\/\//.test(url));
const link=(candidates.find(([mime])=>/utf-8/i.test(mime))||candidates[0])?.[1];
if(link){standardModal('Проверяем открытый текст',`<p>Пробуем открыть полный оригинал напрямую. Если источник не разрешает загрузку, можно скачать файл и импортировать его вручную.</p><div class="skeleton"></div>`,'');
try{const resp=await fetch(link,{signal:AbortSignal.timeout(10000)});if(!resp.ok)throw Error('Текст не был загружен');const text=await resp.text();if(text.trim().length<200)throw Error('Файл пуст');const complete={...b,source:'import',desc:b.desc+' Текст импортирован из Project Gutenberg.'};chapters=chapterize(text);await dbPut({...complete,chapters});savedBooks=[complete,...savedBooks.filter(x=>x.id!==b.id)];view.book=complete;closeModal();toast('Полный оригинал загружен — можно читать офлайн');}
catch(err){standardModal('Скачать полный оригинал',`<p>Сайт источника не разрешил загрузить текст непосредственно в приложение. Скачай TXT и выбери его в ATLAS.</p><a href="${safe(link)}" target="_blank" rel="noopener" class="btn">Открыть оригинальный TXT ↗</a>`,`<button class="btn secondary" data-modal="close">Закрыть</button><button class="btn ghost" data-modal="import">Импортировать скачанное</button>`);return}
}else{toast('У этой записи нет текста TXT. Проверь сайт источника.');return}
}else{$('#bookFile').click();toast('Выбери файл с оригинальным текстом книги');return}
if(!chapters.length){toast('Не удалось извлечь текст');return}view.bookContents={id:b.id,chapters};const pg=st.progress[b.id];view.chapter=Math.min(Math.max(pg?.chapter||0,0),chapters.length-1);view.paragraph=Math.min(Math.max(pg?.para||0,0),chapters[view.chapter].paras.length-1);if(pg){const savedChapter=chapters[view.chapter],excerpt=savedChapter.paras[view.paragraph]||'';standardModal('Продолжить с того же места?',`<span class="eyebrow">СОХРАНЁННАЯ ПОЗИЦИЯ · ${pg.percent||0}%</span><p>Мы запомнили, где ты остановился:</p><div class="muted-box">${safe(savedChapter.title)} · «${safe(trunc(excerpt,150))}»</div>`,`<button class="btn" data-modal="resume-location">Да, продолжить →</button><button class="btn secondary" data-modal="restart-book">С начала</button>`)}else{view.tab='reader';renderReader()}}

function tokens(p){return String(p).split(/([\p{L}\p{M}'’\-]{2,})/u).map((t,i)=>i%2?`<span class="reader-word" data-word="${safe(t)}">${safe(t)}</span>`:safe(t)).join('')}
function renderReader(){const b=view.book,c=view.bookContents,idx=view.chapter,ch=c.chapters[idx],saved=st.progress[b.id],size=Number(st.fontSize)||19;$('#topbar').classList.add('hidden');$('#bottomNav').classList.add('hidden');app.innerHTML=`<div class="reader-mode ${st.theme==='night'?'night':st.theme==='light'?'light':''}" id="readerMode" style="--readSize:${size}px"><header class="reader-top"><button data-reader="exit">←</button><span class="r-title">${safe(b.title)}</span><div class="row" style="gap:7px"><button data-reader="recap" title="Кратко о главе">✧ Итоги</button><button data-reader="settings" title="Настройки чтения">Aa</button></div></header><div class="reader-page"><span class="book-kicker">${safe(b.title)} · ${idx+1} / ${c.chapters.length}</span><h1>${safe(ch.title)}</h1>${ch.paras.map((p,i)=>`<p class="reader-para ${saved?.chapter===idx&&saved?.para===i?'saved':''}" data-para="${i}">${tokens(p)}</p>`).join('')}<div class="reader-footer"><button data-reader="prev" ${idx===0?'disabled':''}>← Назад</button><span class="small-caps" style="color:inherit">${idx+1} / ${c.chapters.length}</span><button data-reader="next" ${idx===c.chapters.length-1?'disabled':''}>Далее →</button></div></div><div class="reader-progress" style="width:${saved?.percent||0}%"></div></div>`;const el=$('#readerMode');el.addEventListener('click',e=>{const word=e.target.closest('.reader-word');if(word){e.stopPropagation();showWord(word.dataset.word);return}const para=e.target.closest('[data-para]');if(para){view.pendingStop=Number(para.dataset.para);let txt=ch.paras[view.pendingStop];standardModal('Сохранить место чтения?',`<p>В следующий раз мы откроем книгу с этого абзаца:</p><div class="muted-box">«${safe(trunc(txt,170))}»</div>`,`<button class="btn" data-modal="save-stop">Да, запомнить</button><button class="btn secondary" data-modal="close">Отмена</button>`);return}const btn=e.target.closest('[data-reader]');if(!btn)return;const a=btn.dataset.reader;if(a==='exit')exitReader();if(a==='next')turnChapter(1);if(a==='prev')turnChapter(-1);if(a==='recap')recap();if(a==='settings')readerSettings();});let tr=null;el.addEventListener('scroll',()=>{clearTimeout(tr);tr=setTimeout(()=>{let p=0;const paras=$$('.reader-para',el);for(let i=0;i<paras.length;i++)if(paras[i].getBoundingClientRect().top<window.innerHeight*.42)p=i;setProgress(b,idx,p,c.chapters,el.scrollTop);$('.reader-progress').style.width=st.progress[b.id].percent+'%';},650)},{passive:true});}
function scrollToPara(pi){const el=$('#readerMode');const node=el?.querySelector(`[data-para="${pi}"]`);if(el&&node){el.scrollTo({top:Math.max(0,node.offsetTop-120),behavior:'instant'});node.classList.add('saved')}}
function exitReader(){// latest scroll position already saved on scroll; safe on immediate exit
const el=$('#readerMode');if(el&&view.bookContents){const paras=$$('.reader-para',el);let p=0;for(let i=0;i<paras.length;i++)if(paras[i].getBoundingClientRect().top<window.innerHeight*.42)p=i;setProgress(view.book,view.chapter,p,view.bookContents.chapters,el.scrollTop)}view.tab='library';view.book=null;view.bookContents=null;render();}
function turnChapter(d){const n=view.chapter+d;if(n<0||n>=view.bookContents.chapters.length)return;view.chapter=n;view.paragraph=0;setProgress(view.book,n,0,view.bookContents.chapters);renderReader();$('#readerMode').scrollTo(0,0)}
function readerSettings(){standardModal('Настройки чтения',`<span class="form-label">Размер шрифта</span><div class="row"><button class="btn secondary sm" data-modal="font-down">А−</button><span id="fontReadLabel">${st.fontSize}px</span><button class="btn secondary sm" data-modal="font-up">А+</button></div><span class="form-label">Фон книги</span><div class="row"><button class="btn secondary sm" data-modal="theme-sepia">Тёплый</button><button class="btn secondary sm" data-modal="theme-light">Светлый</button><button class="btn secondary sm" data-modal="theme-night">Ночной</button></div><p>Нажми на любое слово, чтобы узнать его значение, или на абзац, чтобы сохранить точное место остановки.</p>`)}
async function showWord(word){view.readWord=word.replace(/^[^\p{L}]+|[^\p{L}]+$/gu,'');standardModal(`<span class="word-head">${safe(view.readWord)}</span>`,`<p id="wordMeaning">Ищем значение в открытом словаре…</p><p style="font-size:11px">Некоторые формы слов отсутствуют в словаре. Значение проверяй с учётом контекста.</p>`,`<button class="btn secondary" data-modal="close">К чтению</button><a class="btn ghost" href="https://ru.wiktionary.org/wiki/${encodeURIComponent(view.readWord)}" target="_blank" rel="noopener">Викисловарь ↗</a>`);
try{const w=view.readWord;const url=`https://ru.wiktionary.org/w/api.php?action=parse&prop=wikitext&format=json&origin=*&page=${encodeURIComponent(w)}`;const resp=await fetch(url,{signal:AbortSignal.timeout(6500)});if(!resp.ok)throw new Error();const data=await resp.json();const wiki=data?.parse?.wikitext?.['*']||'';let definitions=wiki.split('\n').filter(l=>/^#(?![:*#])\s*[^#]/.test(l)).slice(0,4).map(line=>line.replace(/^#\s*/, '').replace(/\{\{[^{}]*\}\}/g,'').replace(/\[\[([^\]|]+\|)?([^\]]+)\]\]/g,'$2').replace(/<[^>]+>/g,'').replace(/'{2,}/g,'').replace(/\s+/g,' ').trim()).filter(Boolean);if(!definitions.length)throw new Error();if(view.readWord===w&&$('#wordMeaning'))$('#wordMeaning').textContent=definitions.join(' • ').slice(0,850)
}catch(_){if($('#wordMeaning'))$('#wordMeaning').textContent='Встроенный словарь не нашёл проверенного определения. Нажми «Викисловарь», чтобы посмотреть статью и возможные формы слова.'}}
async function openDB(){return new Promise((resolve,reject)=>{let r=indexedDB.open('atlas-reading-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('books',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});}
function dbTx(mode='readonly'){return db.transaction('books',mode).objectStore('books')}
function dbGet(id){return new Promise((res,rej)=>{let r=dbTx().get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function dbAll(){return new Promise((res,rej)=>{let r=dbTx().getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function dbPut(b){return new Promise((res,rej)=>{let r=dbTx('readwrite').put(b);r.onsuccess=()=>res(true);r.onerror=()=>rej(r.error)})}
function dbDelete(id){return new Promise((res,rej)=>{let r=dbTx('readwrite').delete(id);r.onsuccess=()=>res(true);r.onerror=()=>rej(r.error)})}
function loadScript(url){return new Promise((res,rej)=>{const el=document.createElement('script');el.src=url;el.onload=res;el.onerror=()=>rej(new Error('Не удалось загрузить компонент'));document.head.appendChild(el)})}
async function parseFile(f){const name=f.name.replace(/\.[^.]+$/,'').replaceAll('_',' ');const ext=f.name.split('.').pop().toLowerCase();let text='';if(ext==='txt'){text=await f.text()}else if(ext==='fb2'){let xml=new DOMParser().parseFromString(await f.text(),'application/xml');if(xml.querySelector('parsererror'))throw Error('Ошибка FB2: неверный XML');const body=xml.querySelector('body');if(!body)throw Error('В FB2 нет текста');text=Array.from(body.querySelectorAll('title,p,subtitle,empty-line')).map(n=>n.textContent.trim()).filter(Boolean).join('\n\n')}else if(ext==='epub'){if(!window.JSZip)await loadScript('https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js');const zip=await JSZip.loadAsync(f);const containerFile=zip.file('META-INF/container.xml');if(!containerFile)throw Error('EPUB без файла container.xml');const containerXML=new DOMParser().parseFromString(await containerFile.async('text'),'application/xml');const opfPath=containerXML.querySelector('rootfile')?.getAttribute('full-path');if(!opfPath)throw Error('Не найдено описание EPUB');const opf=zip.file(opfPath);if(!opf)throw Error('EPUB повреждён');const xml=new DOMParser().parseFromString(await opf.async('text'),'application/xml');const manifest={};Array.from(xml.getElementsByTagName('item')).forEach(n=>manifest[n.getAttribute('id')]=n.getAttribute('href'));const spine=Array.from(xml.getElementsByTagName('itemref')).map(n=>n.getAttribute('idref'));const folder=opfPath.includes('/')?opfPath.slice(0,opfPath.lastIndexOf('/')+1):'';const result=[];for(const id of spine){const target=manifest[id];if(!target)continue;const path=folder+decodeURIComponent(target).replace(/^\.\//,'').split('#')[0];const file=zip.file(path);if(!file)continue;const html=await file.async('text');const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('script,style,svg,nav').forEach(el=>el.remove());const paras=Array.from(doc.querySelectorAll('h1,h2,h3,p,li,blockquote')).map(n=>n.textContent.trim()).filter(Boolean);result.push(paras.join('\n\n')||doc.body?.textContent||'')}text=result.join('\n\n')}else if(ext==='pdf'){if(!window.pdfjsLib)await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdf=await pdfjsLib.getDocument({data:new Uint8Array(await f.arrayBuffer())}).promise;const parts=[];for(let page=1;page<=pdf.numPages;page++){const data=await (await pdf.getPage(page)).getTextContent();parts.push(data.items.map(x=>x.str).join(' '));if(page%20===0)toast(`Обрабатываю PDF: ${page}/${pdf.numPages}`)}text=parts.join('\n\n')}else throw Error('Пока поддерживаются только TXT, FB2, EPUB и PDF');if(text.trim().length<80)throw Error('Не удалось извлечь текст. Сканированные PDF без текстового слоя не поддерживаются.');return {title:name,text,chapters:chapterize(text)}}
async function importBook(f){if(!f)return;if(f.size>35*1024*1024){toast('Максимальный размер файла — 35 МБ');return}standardModal('Загружаем книгу',`<p>Обрабатываем «${safe(f.name)}». Файл сохраняется только на этом устройстве.</p><div class="skeleton"></div>`,'');try{const info=await parseFile(f);const id='u-'+crypto.randomUUID();const meta={id,title:info.title,author:'Моя коллекция',category:'Художественная',age:12,desc:`Оригинальный текст из файла ${f.name}.`,tags:['мой файл'],source:'import',index:savedBooks.length};await dbPut({...meta,chapters:info.chapters});savedBooks=[...savedBooks,meta];closeModal();view.tab='library';view.book=meta;render();toast('Книга добавлена! Можно читать офлайн.');}catch(e){standardModal('Не получилось добавить книгу',`<p>${safe(e?.message||'Попробуй другой файл.')}</p>`)}finally{$('#bookFile').value=''}}
async function exportBackup(){try{const books=await dbAll();const payload={type:'ATLAS_BACKUP',version:3,created:new Date().toISOString(),state:st,books};const blob=new Blob([JSON.stringify(payload)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`atlas-backup-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Резервная копия создана')}catch(e){toast('Ошибка экспорта: '+e.message)}}
async function importBackup(file){try{const payload=JSON.parse(await file.text());if(payload.type!=='ATLAS_BACKUP'||!Array.isArray(payload.books))throw Error('Это не резервная копия ATLAS');for(const item of payload.books)if(item?.id&&Array.isArray(item?.chapters))await dbPut(item);const restored=payload.state||{};st={...DEFAULT,...restored,likes:[...new Set([...st.likes,...(restored.likes||[])])],progress:{...st.progress,...(restored.progress||{})},recent:[...new Set([...(restored.recent||[]),...st.recent])]};save();savedBooks=(await dbAll()).map(({chapters,text,...meta})=>meta);closeModal();tab('library');toast('Книги и прогресс восстановлены')}catch(e){standardModal('Ошибка восстановления',`<p>${safe(e.message)}</p>`)}}
async function searchWorld(source){const q=view.query.trim();if(!q){toast('Введи название книги или автора в поиск');return}view.onlineBusy=true;render();try{if(source==='world'){const r=await fetch(`https://openlibrary.org/search.json?q=${encodeURIComponent(q)}&limit=12&fields=key,title,author_name,first_publish_year,cover_i,language`);if(!r.ok)throw Error('Поиск сейчас недоступен');const data=await r.json();view.openLibraryResults=(data.docs||[]).filter(x=>x.key&&x.title).map((d,i)=>({id:`ol-${d.key.replaceAll('/','-')}`,title:d.title,author:d.author_name?.slice(0,2).join(', ')||'Автор не указан',category:'Мировой каталог',age:12,image:d.cover_i?`https://covers.openlibrary.org/b/id/${d.cover_i}-M.jpg`:null,desc:`Библиографическая запись Open Library. Первое издание: ${d.first_publish_year||'не указано'}. Полный текст в ATLAS не предоставлен.`,external:`https://openlibrary.org${d.key}`,source:'openlibrary',index:i,tags:[]}));}else{const r=await fetch(`https://gutendex.com/books/?search=${encodeURIComponent(q)}`);if(!r.ok)throw Error('Поиск сейчас недоступен');const data=await r.json();view.gutResults=(data.results||[]).filter(x=>x.copyright===false).slice(0,18).map((d,i)=>({id:`pg-${d.id}`,title:d.title,author:d.authors?.map(x=>x.name).join(', ')||'Автор не указан',category:'Классика',age:12,desc:'Свободная книга из проекта Gutenberg. Юридический статус может зависеть от страны.',tags:[],source:'gutenberg',index:i,image:d.formats?.['image/jpeg']||null,formats:d.formats,external:`https://www.gutenberg.org/ebooks/${d.id}`}));}}catch(e){toast(e.message||'Ошибка поиска. Проверь соединение.')}finally{view.onlineBusy=false;render();const target=source==='world'?'Результаты мирового каталога':'Свободные тексты Project Gutenberg';setTimeout(()=>[...$$('h2')].find(x=>x.textContent===target)?.scrollIntoView({behavior:'smooth'}),80)}}
const modalHandlers={close:closeModal,'resume-location':()=>{closeModal();view.tab='reader';renderReader();setTimeout(()=>scrollToPara(view.paragraph),70)},'restart-book':()=>{closeModal();view.chapter=0;view.paragraph=0;setProgress(view.book,0,0,view.bookContents.chapters);view.tab='reader';renderReader();$('#readerMode').scrollTo(0,0)},import:()=>{closeModal();$('#bookFile').click()},'save-stop':()=>{if(!view.bookContents)return;setProgress(view.book,view.chapter,view.pendingStop,view.bookContents.chapters);$$('.reader-para').forEach(x=>x.classList.toggle('saved',+x.dataset.para===view.pendingStop));$('.reader-progress').style.width=st.progress[view.book.id].percent+'%';closeModal();toast('Место сохранено ✦')},'font-down':()=>{st.fontSize=Math.max(14,st.fontSize-1);save();closeModal();renderReader()},'font-up':()=>{st.fontSize=Math.min(30,st.fontSize+1);save();closeModal();renderReader()},'theme-sepia':()=>{st.theme='sepia';save();closeModal();renderReader()},'theme-light':()=>{st.theme='light';save();closeModal();renderReader()},'theme-night':()=>{st.theme='night';save();closeModal();renderReader()},'delete-confirm':async()=>{const b=view.book;await dbDelete(b.id);savedBooks=savedBooks.filter(x=>x.id!==b.id);delete st.progress[b.id];st.recent=st.recent.filter(x=>x!==b.id);save();closeModal();tab('library');toast('Книга удалена')}};
document.addEventListener('click',async e=>{const md=e.target.closest('[data-modal]');if(md){modalHandlers[md.dataset.modal]?.();return}const ct=e.target.closest('[data-category]');if(ct){view.category=ct.dataset.category;tab('catalog');return}const ag=e.target.closest('[data-age]');if(ag){view.age=ag.dataset.age;render();return}const pr=e.target.closest('[data-persona]');if(pr){st.persona=pr.dataset.persona;save();render();return}const prompt=e.target.closest('[data-prompt]');if(prompt){view.problem=prompt.dataset.prompt;st.persona=/15/.test(view.problem)?'15':st.persona;view.rec=makeRecommendations(view.problem,st.persona);view.tab='advisor';view.book=null;render();return}const btn=e.target.closest('[data-action]');if(!btn)return;const a=btn.dataset.action;
if(a==='to-catalog')tab('catalog');else if(a==='to-library')tab('library');else if(a==='to-advisor')tab('advisor');else if(a==='age-15'){st.persona='15';view.problem='Мне 15, с чего начать?';view.rec=makeRecommendations(view.problem,'15');save();tab('advisor')}else if(a==='open-sample')openBook('intro');else if(a==='resume-first'){const b=bookById(st.recent[0]);if(b){view.book=b;await beginReading()}else openBook('intro')}else if(a==='back'){view.book=null;render()}else if(a==='read')await beginReading();else if(a==='favorite'){const id=view.book.id;st.likes=st.likes.includes(id)?st.likes.filter(x=>x!==id):[id,...st.likes];if(st.likes.includes(id)&&(view.book.source==='openlibrary'||view.book.source==='gutenberg'))st.savedCatalog[id]=view.book;save();render();toast(st.likes.includes(id)?'Добавлено в сохранённое':'Удалено из сохранённого')}else if(a==='import-book')$('#bookFile').click();else if(a==='set-cover')$('#coverFile').click();else if(a==='delete-book')standardModal('Удалить книгу?',`<p>Файл «${safe(view.book.title)}» и её прогресс будут удалены с этого устройства. Это нельзя отменить без резервной копии.</p>`,`<button class="btn secondary" data-modal="close">Отмена</button><button class="btn" data-modal="delete-confirm">Удалить</button>`);else if(a==='get-recs'){view.problem=$('#problemInput')?.value||'';view.rec=makeRecommendations(view.problem,st.persona);render();setTimeout(()=>$('.recommendation')?.scrollIntoView({behavior:'smooth'}),80)}else if(a==='world-search')searchWorld('world');else if(a==='gutenberg-search')searchWorld('gutenberg');else if(a==='export')exportBackup();else if(a==='restore')$('#backupFile').click();});
$$('.bottom-nav button').forEach(btn=>btn.addEventListener('click',()=>tab(btn.dataset.tab)));
$('#settingsBtn').addEventListener('click',()=>standardModal('Параметры ATLAS',`<p>Читай в своём темпе. Прогресс сохраняется на устройстве автоматически.</p><span class="form-label">Цель чтения в день (минуты)</span><input type="number" id="dailyGoal" min="5" max="180" value="${st.goal}"><p>Аккаунт: ${TG?.initDataUnsafe?.user?.first_name?safe(TG.initDataUnsafe.user.first_name)+' (Telegram)':'Гостевой режим'}.</p><div class="muted-box">Важно: данные пока не синхронизируются между устройствами. В Telegram WebApp каталог работает, но для подключения к боту нужен опубликованный HTTPS-адрес.</div>`,`<button class="btn" data-modal="save-goal">Сохранить</button><button class="btn secondary" data-modal="close">Закрыть</button>`));
modalHandlers['save-goal']=()=>{st.goal=Math.min(180,Math.max(5,Number($('#dailyGoal')?.value)||15));save();closeModal();render();toast('Цель сохранена')};
$('#bookFile').addEventListener('change',e=>importBook(e.target.files?.[0]));
$('#backupFile').addEventListener('change',e=>{if(e.target.files?.[0])importBackup(e.target.files[0]);e.target.value=''});
$('#coverFile').addEventListener('change',e=>{const f=e.target.files?.[0];if(!f||!view.book)return;if(f.size>2_000_000){toast('Обложка должна быть меньше 2 МБ');return}const reader=new FileReader();reader.onload=()=>{st.customCovers[view.book.id]=reader.result;save();render();toast('Обложка обновлена')};reader.readAsDataURL(f);e.target.value=''});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!overlay.hidden)closeModal();else if(view.tab==='reader')exitReader();else if(view.book){view.book=null;render()}}});
async function boot(){try{db=await openDB();savedBooks=(await dbAll()).map(({chapters,text,...meta})=>meta)}catch(e){console.error('IndexedDB unavailable',e);savedBooks=[];toast('Хранилище файлов недоступно: открой приложение в обычном браузере')}view.tab='home';render()}
boot();
